insert into public.curriculum_nodes (id, template_id, parent_id, kind, key, title, summary, position) values ('history-early-civilizations/floodplain-review', 'history-early-civilizations', 'history-early-civilizations/ancient-mesopotamia', 'topic', 'floodplain-review', 'The challenge of the floodplain', 'Bring geography and farming together: how did people turn a dry, flood-prone plain into the world’s first cities?', 2) on conflict (id) do update set template_id = excluded.template_id, parent_id = excluded.parent_id, kind = excluded.kind, key = excluded.key, title = excluded.title, summary = excluded.summary, position = excluded.position;
insert into public.curriculum_nodes (id, template_id, parent_id, kind, key, title, summary, position) values ('history-early-civilizations/connect-land-and-cities', 'history-early-civilizations', 'history-early-civilizations/floodplain-review', 'objective', 'connect-land-and-cities', 'Connect the environment of southern Mesopotamia to how its people farmed, built and traded.', '', 0) on conflict (id) do update set template_id = excluded.template_id, parent_id = excluded.parent_id, kind = excluded.kind, key = excluded.key, title = excluded.title, summary = excluded.summary, position = excluded.position;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/land-between-rivers', 'history-early-civilizations', 'land-between-rivers', 'The land between the rivers', '“Mesopotamia” comes from a Greek word meaning “between rivers”: the Tigris and the Euphrates.', array['The name describes the land between the Tigris and Euphrates rivers. Used broadly, the region takes in what is now eastern Syria, southeastern Turkey and most of Iraq.', 'Mesopotamian civilization influenced a wide area of the Middle East, and its trade and ideas reached as far as Egypt, the Mediterranean and the Indus valley.']::text[], array['The Greek name is a description, not what the people who lived there called their land.']::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/geography']::text[], 'established', '[{"sourceId":"history-early-civilizations/britannica-mesopotamia"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/alluvial-plain', 'history-early-civilizations', 'alluvial-plain', 'The alluvial plain', 'Southern Mesopotamia is flat land built up from river silt, where slow rivers flood and shift course.', array['South of the area around modern Baghdad the land is a flat alluvial plain: between Baghdad and the Persian Gulf it drops only about 30 metres.', 'Because the water flows slowly, the rivers drop heavy loads of silt and their beds rise. Without high banks (dikes) they overflow and can even change course.', 'Over thousands of years the rivers have shifted, partly because of human changes, so the mounds (tells) hiding ancient cities often lie far from today’s rivers.']::text[], '{}'::text[], array['Explains why controlling water with dikes and canals was central to life in the south.']::text[], array['history-early-civilizations/low-rainfall', 'history-early-civilizations/southern-marshes']::text[], array['history-early-civilizations/geography']::text[], 'established', '[{"sourceId":"history-early-civilizations/britannica-mesopotamia"},{"sourceId":"history-early-civilizations/britannica-tigris-euphrates"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/low-rainfall', 'history-early-civilizations', 'low-rainfall', 'Heat, little rain and the need for irrigation', 'With very little rain, the southern plain could only be farmed reliably once people irrigated it.', array['High temperatures and very low rainfall leave the ground of the plain hard and dry, unsuitable for crops for at least eight months of the year.', 'Farming without the risk of crop failure arrived in the heart of Mesopotamia only after irrigation: canals that carried river water across wide areas.', 'The soil itself is extremely fertile. With irrigation and proper drainage it produces in abundance, which is why the south could support a large population.']::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/alluvial-plain', 'history-early-civilizations/irrigation-moves-south']::text[], array['history-early-civilizations/geography', 'history-early-civilizations/agriculture']::text[], 'established', '[{"sourceId":"history-early-civilizations/britannica-mesopotamia"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/southern-marshes', 'history-early-civilizations', 'southern-marshes', 'The southern marshes', 'The far south, near the rivers’ meeting point, is a region of marshes and reed swamps.', array['In the extreme south there are extensive marshes and reed swamps. Probably since early times they have also served as a refuge for displaced people.', 'Reeds were one of the region’s plentiful resources, used for many products.']::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/alluvial-plain', 'history-early-civilizations/scarce-resources']::text[], array['history-early-civilizations/geography']::text[], 'consensus', '[{"sourceId":"history-early-civilizations/britannica-mesopotamia"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/scarce-resources', 'history-early-civilizations', 'scarce-resources', 'Rich soil, scarce materials', 'Wood, stone and metal were rare in the south, so trade was built into life from the start.', array['Southern Mesopotamia had plenty of farm and animal products, fish, dates and reeds, and bitumen springs at Hīt on the Euphrates. But wood, stone and metal were rare or missing.', 'The date palm’s wood was good only for rough beams. Stone was mostly lacking in the south. Metal and precious stones could only be obtained in the mountains.', 'So the south in particular was a land of trade from the very beginning.']::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/clay-civilization', 'history-early-civilizations/long-distance-trade', 'history-early-civilizations/abundant-produce']::text[], array['history-early-civilizations/geography']::text[], 'established', '[{"sourceId":"history-early-civilizations/britannica-mesopotamia"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/clay-civilization', 'history-early-civilizations', 'clay-civilization', 'A civilization of clay', 'Clay was everywhere: mud-brick buildings, pottery, figurines and writing tablets.', array['Architecture was almost entirely mud brick, and clay was used for figurines and pottery in great number and variety.', 'Clay was also the writing surface: the earliest records at Uruk were drawn on clay tablets.']::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/scarce-resources', 'history-early-civilizations/writing-for-administration']::text[], array['history-early-civilizations/geography']::text[], 'established', '[{"sourceId":"history-early-civilizations/britannica-mesopotamia"},{"sourceId":"history-early-civilizations/met-uruk"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/long-distance-trade', 'history-early-civilizations', 'long-distance-trade', 'Long-distance trade', 'By c. 2900–2350 BCE, Sumer traded with the Persian Gulf, Iran, Afghanistan and the Indus Valley.', array['Excavated objects and texts show long-distance trade between Sumer and the Persian Gulf region, Iran, Afghanistan and the cities of the Indus Valley in the Early Dynastic period (c. 2900–2350 BCE).', 'At Ur, graves contained objects made of imported gold, silver, lapis lazuli and carnelian.', 'Rulers of the period increasingly sought luxury materials, obtained by trade or by conquest, to display their power.']::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/scarce-resources']::text[], array['history-early-civilizations/geography']::text[], 'established', '[{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"},{"sourceId":"history-early-civilizations/met-uruk"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/salinization-debate', 'history-early-civilizations', 'salinization-debate', 'The salt-and-silt debate', 'Did salt build-up in irrigated soil help bring down southern cities? Historians disagree.', array['In 1958 Thorkild Jacobsen and Robert M. Adams argued that progressive changes in soil salinity and sedimentation contributed to the breakup of past civilizations in southern Mesopotamia.', 'In 1985 Marvin A. Powell published a critique of this “theory of progressive salinization”, challenging how strongly the evidence supports it.', 'This is a debated interpretation, not an established fact. It is a good example of how historians test each other’s arguments against the evidence.']::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/low-rainfall']::text[], array['history-early-civilizations/geography', 'history-early-civilizations/cause-effect']::text[], 'debated', '[{"sourceId":"history-early-civilizations/jacobsen-adams-1958"},{"sourceId":"history-early-civilizations/powell-1985"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/first-farmers', 'history-early-civilizations', 'first-farmers', 'The first farmers', 'Farming began in the wetter hills on Mesopotamia’s borders, long before it reached the southern plain.', array['Farming seems to have begun in the higher-rainfall zones and hilly borders of Mesopotamia, in the 10th millennium BCE.', 'By 8000 BCE farming communities were established in northern Mesopotamia, the eastern end of the Fertile Crescent.', 'At Jarmo, from about 8000–7000 BCE, archaeologists found the first evidence of domesticated grains (wheat and barley) and animals (sheep, goat, pig and cattle).']::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/irrigation-moves-south']::text[], array['history-early-civilizations/agriculture']::text[], 'consensus', '[{"sourceId":"history-early-civilizations/britannica-mesopotamia"},{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/irrigation-moves-south', 'history-early-civilizations', 'irrigation-moves-south', 'Irrigation moves south', 'Early in the 6th millennium BCE, farmers relying on irrigation settled further south along the rivers.', array['Early in the sixth millennium BCE, farming communities that relied on irrigation rather than rainfall settled further and further south along the Tigris and Euphrates.', 'Irrigation farming on the alluvial plain has continued for about 7,000 years, leaving a landscape of old canals, levees and thousands of ancient settlement sites.']::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/first-farmers', 'history-early-civilizations/low-rainfall', 'history-early-civilizations/ubaid-culture']::text[], array['history-early-civilizations/agriculture']::text[], 'consensus', '[{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"},{"sourceId":"history-early-civilizations/britannica-tigris-euphrates"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/abundant-produce', 'history-early-civilizations', 'abundant-produce', 'Surplus from the floodplain', 'Irrigated land produced grain, dates, wool, fish and reed goods in surplus, enough to export.', array['Farming, herding, fishing, date-palm growing and reed working produced grain, vegetables, meat, leather, wool, fish, dates and reed products in plenty, more than people needed at home.', 'This surplus could be traded for the wood, stone and metal the south lacked.']::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/scarce-resources', 'history-early-civilizations/irrigation-moves-south']::text[], array['history-early-civilizations/agriculture']::text[], 'established', '[{"sourceId":"history-early-civilizations/britannica-mesopotamia"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/chronology-uncertain', 'history-early-civilizations', 'chronology-uncertain', 'Why early dates say “c.”', 'Dates for early Mesopotamia are approximate; scholars use different chronologies.', array['No universally accepted chronology exists for the whole ancient Near East. Reign dates in Babylonia are certain only back to 747 BCE.', 'Earlier events can often be put in order relative to each other, but neither surviving documents nor scientific methods such as carbon-14 dating fix them exactly in time.', 'This course follows the dates used by The Metropolitan Museum of Art. Other books may give somewhat different dates for the same periods.']::text[], '{}'::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/agriculture', 'history-early-civilizations/chronology']::text[], 'established', '[{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/ubaid-culture', 'history-early-civilizations', 'ubaid-culture', 'The Ubaid culture', 'A southern culture (c. 5000–4000 BCE in the Met’s chronology) known for painted pottery and growing temples at Eridu.', array['Ubaid culture, recognised by distinctive painted pottery made on a slow wheel, arose in the south. As it spread, local pottery styles were replaced across Mesopotamia and beyond.', 'Throughout the period, a sequence of ever more massive mud-brick temples was built at Eridu.', 'The Met dates it to about 5000–4000 BCE; other scholars give earlier start dates, a reminder that early dates are approximate.']::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/uruk-period', 'history-early-civilizations/chronology-uncertain']::text[], array['history-early-civilizations/agriculture']::text[], 'consensus', '[{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/uruk-period', 'history-early-civilizations', 'uruk-period', 'Uruk and the first cities', 'Villages gave way to larger settlements, and by c. 3200 BCE Uruk was a true city.', array['Between about 4000 and 3500 BCE, smaller Ubaid villages gave way to fewer but larger settlements in the south. From this emerged the Uruk culture, with mass-produced pottery.', 'Between about 3500 and 3000 BCE, cities emerged across the region, most of all in the south, centred on monumental mud-brick temples set on high platforms.', 'By around 3200 BCE Uruk was the largest settlement in southern Mesopotamia, if not the world: a true city of monumental buildings decorated with clay-cone mosaics, with new kinds of sculpture and metal casting.']::text[], '{}'::text[], '{}'::text[], array['history-early-civilizations/ubaid-culture', 'history-early-civilizations/writing-for-administration']::text[], array['history-early-civilizations/agriculture']::text[], 'consensus', '[{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"},{"sourceId":"history-early-civilizations/met-uruk"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.codex_entries (id, template_id, key, title, summary, explanation, examples, applications, related_ids, competency_ids, certainty, citations) values ('history-early-civilizations/writing-for-administration', 'history-early-civilizations', 'writing-for-administration', 'Writing began as record keeping', 'The earliest pictographs on clay tablets recorded goods and workers’ rations.', array['At Uruk, simple pictographs drawn on clay tablets recorded the management of goods and the allocation of workers’ rations. They are the forerunners of cuneiform writing.', 'Clay tokens used for record keeping slowly disappeared as cuneiform developed. Signs were first incised and later pressed into clay with a reed stylus.', 'In the same period, stamp seals were largely replaced by cylinder seals, which allowed a wider range of designs.']::text[], array['One early tablet in the Met’s collection is an administrative account of barley distribution.']::text[], '{}'::text[], array['history-early-civilizations/uruk-period', 'history-early-civilizations/clay-civilization']::text[], array['history-early-civilizations/agriculture', 'history-early-civilizations/source-analysis']::text[], 'consensus', '[{"sourceId":"history-early-civilizations/met-uruk"},{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"}]'::jsonb) on conflict (id) do update set template_id = excluded.template_id, key = excluded.key, title = excluded.title, summary = excluded.summary, explanation = excluded.explanation, examples = excluded.examples, applications = excluded.applications, related_ids = excluded.related_ids, competency_ids = excluded.competency_ids, certainty = excluded.certainty, citations = excluded.citations;
insert into public.learning_activities (id, template_id, objective_id, key, kind, title, position, competency_ids, estimated_minutes, sections, introduces_ids, target_stage, question_count) values ('history-early-civilizations/lesson-land-between-rivers', 'history-early-civilizations', 'history-early-civilizations/describe-the-land', 'lesson-land-between-rivers', 'lesson', 'The land between the rivers', 0, array['history-early-civilizations/geography']::text[], 6, '[{"heading":"A name that describes a place","paragraphs":["“Mesopotamia” comes from a Greek word meaning “between rivers”. The rivers are the Tigris and the Euphrates. In the broad sense the region covers what is now eastern Syria, southeastern Turkey and most of Iraq."],"certainty":"established","citations":[{"sourceId":"history-early-civilizations/britannica-mesopotamia"}]},{"heading":"A flat, silty plain","paragraphs":["In the south the land is almost perfectly flat. Between Baghdad and the Persian Gulf it falls only about 30 metres. The rivers move slowly, drop their silt and raise their own beds, so without high banks they overflow, and sometimes change course entirely.","Over the millennia the rivers have wandered, so the mounds that hide ancient cities often sit far from today’s riverbanks."],"certainty":"established","citations":[{"sourceId":"history-early-civilizations/britannica-mesopotamia"},{"sourceId":"history-early-civilizations/britannica-tigris-euphrates"}]},{"heading":"Too dry to farm without help","paragraphs":["Heat and very little rain leave the southern plain hard and dry for at least eight months of the year. Reliable farming came to the heart of Mesopotamia only once people dug canals to carry river water to their fields.","The reward was great: the soil is extremely fertile, and with irrigation and drainage it can feed a large population."],"certainty":"established","citations":[{"sourceId":"history-early-civilizations/britannica-mesopotamia"}]},{"heading":"Marshes in the far south","paragraphs":["Near where the rivers meet lies a region of marshes and reed swamps, rich in reeds."],"certainty":"consensus","citations":[{"sourceId":"history-early-civilizations/britannica-mesopotamia"}]}]'::jsonb, array['history-early-civilizations/land-between-rivers', 'history-early-civilizations/alluvial-plain', 'history-early-civilizations/low-rainfall', 'history-early-civilizations/southern-marshes']::text[], null, null) on conflict (id) do update set template_id = excluded.template_id, objective_id = excluded.objective_id, key = excluded.key, kind = excluded.kind, title = excluded.title, position = excluded.position, competency_ids = excluded.competency_ids, estimated_minutes = excluded.estimated_minutes, sections = excluded.sections, introduces_ids = excluded.introduces_ids, target_stage = excluded.target_stage, question_count = excluded.question_count;
insert into public.learning_activities (id, template_id, objective_id, key, kind, title, position, competency_ids, estimated_minutes, sections, introduces_ids, target_stage, question_count) values ('history-early-civilizations/check-the-land', 'history-early-civilizations', 'history-early-civilizations/describe-the-land', 'check-the-land', 'assessment', 'Check: the land between the rivers', 1, array['history-early-civilizations/geography']::text[], null, null, '{}'::text[], 2, 5) on conflict (id) do update set template_id = excluded.template_id, objective_id = excluded.objective_id, key = excluded.key, kind = excluded.kind, title = excluded.title, position = excluded.position, competency_ids = excluded.competency_ids, estimated_minutes = excluded.estimated_minutes, sections = excluded.sections, introduces_ids = excluded.introduces_ids, target_stage = excluded.target_stage, question_count = excluded.question_count;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-name-meaning', 'history-early-civilizations/check-the-land', 'geo-name-meaning', 'history-early-civilizations/land-between-rivers', 'single_choice', 1, 0, '{"key":"geo-name-meaning","concept":"land-between-rivers","difficulty":1,"prompt":"The name “Mesopotamia” comes from Greek. What does it mean?","explanation":"The name means “between rivers”, describing the land between the Tigris and the Euphrates.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"black-land","text":"Black land"},{"key":"between-rivers","text":"Between rivers"},{"key":"land-of-cities","text":"Land of cities"},{"key":"two-kings","text":"Land of the two kings"}],"answer":"between-rivers"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-two-rivers', 'history-early-civilizations/check-the-land', 'geo-two-rivers', 'history-early-civilizations/land-between-rivers', 'single_choice', 1, 1, '{"key":"geo-two-rivers","concept":"land-between-rivers","difficulty":1,"prompt":"Which two rivers give Mesopotamia its name?","explanation":"Mesopotamia is the land between the Tigris and the Euphrates. The Nile is Egypt’s river.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"nile-jordan","text":"The Nile and the Jordan"},{"key":"tigris-nile","text":"The Tigris and the Nile","errorCategory":"related_concept_confusion"},{"key":"tigris-euphrates","text":"The Tigris and the Euphrates"},{"key":"indus-ganges","text":"The Indus and the Ganges"}],"answer":"tigris-euphrates"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-flat-plain', 'history-early-civilizations/check-the-land', 'geo-flat-plain', 'history-early-civilizations/alluvial-plain', 'single_choice', 2, 2, '{"key":"geo-flat-plain","concept":"alluvial-plain","difficulty":2,"prompt":"The southern plain drops only about 30 metres between Baghdad and the Persian Gulf. What is one result?","explanation":"On such flat land the rivers flow slowly, deposit silt and build up their beds. Without dikes they overflow and may shift course.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"canyons","text":"The rivers run fast and cut deep canyons","errorCategory":"conceptual_misunderstanding"},{"key":"silt-floods","text":"Slow rivers drop silt and raise their beds, so they overflow and can change course"},{"key":"rocky","text":"The land is too rocky to farm"},{"key":"freeze","text":"The rivers freeze over every winter"}],"answer":"silt-floods"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-why-irrigate', 'history-early-civilizations/check-the-land', 'geo-why-irrigate', 'history-early-civilizations/low-rainfall', 'single_choice', 2, 3, '{"key":"geo-why-irrigate","concept":"low-rainfall","difficulty":2,"prompt":"Why did farming in southern Mesopotamia depend on irrigation?","explanation":"The soil was very fertile; the problem was water. With little rain, the plain needed canals bringing river water to the fields.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"salty-rivers","text":"The river water was too salty to use","errorCategory":"related_concept_confusion"},{"key":"poor-soil","text":"The soil was rocky and infertile","errorCategory":"conceptual_misunderstanding"},{"key":"dry","text":"Very low rainfall and high heat leave the ground too dry to farm for much of the year"},{"key":"law","text":"Religious law banned farming that relied on rain"}],"answer":"dry"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-far-south', 'history-early-civilizations/check-the-land', 'geo-far-south', 'history-early-civilizations/southern-marshes', 'single_choice', 1, 4, '{"key":"geo-far-south","concept":"southern-marshes","difficulty":1,"prompt":"What kind of landscape covers the far south of Mesopotamia, near where the rivers meet?","explanation":"The extreme south is a region of extensive marshes and reed swamps.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"mountains","text":"Snowy mountains"},{"key":"forest","text":"Dense forest"},{"key":"highlands","text":"Rocky highlands"},{"key":"marshes","text":"Marshes and reed swamps"}],"answer":"marshes"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-match-features', 'history-early-civilizations/check-the-land', 'geo-match-features', 'history-early-civilizations/alluvial-plain', 'matching', 3, 5, '{"key":"geo-match-features","concept":"alluvial-plain","difficulty":3,"prompt":"Match each feature of southern Mesopotamia to its description.","explanation":"The plain is built of river silt; the far south is marsh and reed swamp; dikes are the high banks that keep rivers from overflowing.","errorCategory":"related_concept_confusion","citations":[{"source":"britannica-mesopotamia"}],"kind":"matching","left":[{"key":"plain","text":"Alluvial plain"},{"key":"marsh","text":"Marshes"},{"key":"dikes","text":"Dikes"}],"right":[{"key":"banks","text":"High banks that stop rivers overflowing"},{"key":"flat-silt","text":"Flat land built up from river silt"},{"key":"reeds","text":"Reed swamps in the far south"}],"answer":{"plain":"flat-silt","marsh":"reeds","dikes":"banks"}}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-dry-months', 'history-early-civilizations/check-the-land', 'geo-dry-months', 'history-early-civilizations/low-rainfall', 'single_choice', 3, 6, '{"key":"geo-dry-months","concept":"low-rainfall","difficulty":3,"prompt":"Without irrigation, for how much of the year is the southern plain too hard and dry for crops?","explanation":"Heat and very low rainfall leave the plain unsuitable for crops for at least eight months a year.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"never","text":"Never: it can be farmed all year","errorCategory":"conceptual_misunderstanding"},{"key":"two-weeks","text":"About two weeks"},{"key":"eight-months","text":"At least eight months"},{"key":"one-month","text":"About one month"}],"answer":"eight-months"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-shifting-rivers', 'history-early-civilizations/check-the-land', 'geo-shifting-rivers', 'history-early-civilizations/alluvial-plain', 'single_choice', 2, 7, '{"key":"geo-shifting-rivers","concept":"alluvial-plain","difficulty":2,"prompt":"Ruins of ancient Sumerian cities often lie far from today’s rivers. What is the best explanation?","explanation":"Both rivers have shifted greatly over the millennia, so ancient city mounds often bear no relation to present-day rivers.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-tigris-euphrates"}],"kind":"single_choice","options":[{"key":"desert-on-purpose","text":"Cities were deliberately built far from water","errorCategory":"conceptual_misunderstanding"},{"key":"shifted","text":"The rivers have shifted course over thousands of years"},{"key":"earthquakes","text":"Earthquakes moved the cities"},{"key":"rebuilt","text":"Modern governments moved the ruins"}],"answer":"shifted"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.learning_activities (id, template_id, objective_id, key, kind, title, position, competency_ids, estimated_minutes, sections, introduces_ids, target_stage, question_count) values ('history-early-civilizations/lesson-plenty-and-scarcity', 'history-early-civilizations', 'history-early-civilizations/explain-resources', 'lesson-plenty-and-scarcity', 'lesson', 'Plenty and scarcity', 0, array['history-early-civilizations/geography']::text[], 7, '[{"heading":"What the land gave","paragraphs":["Irrigated fields, herds, fisheries, date palms and reed beds gave southern Mesopotamia grain, vegetables, meat, leather, wool, fish, dates and reed goods, more than people needed. There were even bitumen springs at Hīt on the Euphrates."],"certainty":"established","citations":[{"sourceId":"history-early-civilizations/britannica-mesopotamia"}]},{"heading":"What it lacked","paragraphs":["Wood, stone and metal were rare or missing. Date-palm wood was good only for rough beams, stone was mostly lacking in the south, and metal and precious stones came only from the mountains. From the start, the south had to trade."],"certainty":"established","citations":[{"sourceId":"history-early-civilizations/britannica-mesopotamia"}]},{"heading":"A civilization of clay","paragraphs":["Clay filled the gap. Buildings were almost all mud brick, and clay became pottery, figurines and, at Uruk, the tablets on which the earliest records were written."],"certainty":"established","citations":[{"sourceId":"history-early-civilizations/britannica-mesopotamia"},{"sourceId":"history-early-civilizations/met-uruk"}]},{"heading":"Trade over long distances","paragraphs":["By the Early Dynastic period (c. 2900–2350 BCE), objects and texts show trade between Sumer and the Persian Gulf, Iran, Afghanistan and the cities of the Indus Valley. Graves at Ur held objects of imported gold, silver, lapis lazuli and carnelian."],"certainty":"established","citations":[{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"}]},{"heading":"A debate: did salt bring decline?","paragraphs":["In 1958 Thorkild Jacobsen and Robert M. Adams argued that slowly rising salt and silt in irrigated soils contributed to the breakup of southern Mesopotamian civilization. In 1985 Marvin A. Powell published a critique of that theory.","Treat this as a debated interpretation. Historians still argue about how much it explains."],"certainty":"debated","citations":[{"sourceId":"history-early-civilizations/jacobsen-adams-1958"},{"sourceId":"history-early-civilizations/powell-1985"}]}]'::jsonb, array['history-early-civilizations/scarce-resources', 'history-early-civilizations/clay-civilization', 'history-early-civilizations/long-distance-trade', 'history-early-civilizations/salinization-debate']::text[], null, null) on conflict (id) do update set template_id = excluded.template_id, objective_id = excluded.objective_id, key = excluded.key, kind = excluded.kind, title = excluded.title, position = excluded.position, competency_ids = excluded.competency_ids, estimated_minutes = excluded.estimated_minutes, sections = excluded.sections, introduces_ids = excluded.introduces_ids, target_stage = excluded.target_stage, question_count = excluded.question_count;
insert into public.learning_activities (id, template_id, objective_id, key, kind, title, position, competency_ids, estimated_minutes, sections, introduces_ids, target_stage, question_count) values ('history-early-civilizations/check-plenty-and-scarcity', 'history-early-civilizations', 'history-early-civilizations/explain-resources', 'check-plenty-and-scarcity', 'assessment', 'Check: plenty and scarcity', 1, array['history-early-civilizations/geography']::text[], null, null, '{}'::text[], 3, 4) on conflict (id) do update set template_id = excluded.template_id, objective_id = excluded.objective_id, key = excluded.key, kind = excluded.kind, title = excluded.title, position = excluded.position, competency_ids = excluded.competency_ids, estimated_minutes = excluded.estimated_minutes, sections = excluded.sections, introduces_ids = excluded.introduces_ids, target_stage = excluded.target_stage, question_count = excluded.question_count;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-rare-materials', 'history-early-civilizations/check-plenty-and-scarcity', 'geo-rare-materials', 'history-early-civilizations/scarce-resources', 'single_choice', 2, 0, '{"key":"geo-rare-materials","concept":"scarce-resources","difficulty":2,"prompt":"Which materials were rare or missing in southern Mesopotamia?","explanation":"The south had plenty of clay, reeds, bitumen, grain, dates, fish and wool. Wood, stone and metal were rare or absent.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"clay-reeds","text":"Clay, reeds and bitumen","errorCategory":"related_concept_confusion"},{"key":"wood-stone-metal","text":"Wood, stone and metal"},{"key":"grain-dates","text":"Grain and dates","errorCategory":"related_concept_confusion"},{"key":"fish-wool","text":"Fish and wool","errorCategory":"related_concept_confusion"}],"answer":"wood-stone-metal"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-why-trade', 'history-early-civilizations/check-plenty-and-scarcity', 'geo-why-trade', 'history-early-civilizations/scarce-resources', 'single_choice', 2, 1, '{"key":"geo-why-trade","concept":"scarce-resources","difficulty":2,"prompt":"Why was southern Mesopotamia a land of trade from the very beginning?","explanation":"The south produced a food surplus but had no metal or precious stones; those came only from the mountains, so they had to be traded for.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"no-rivers","text":"It had no rivers for transport","errorCategory":"conceptual_misunderstanding"},{"key":"little-food","text":"Its farmers could not grow enough food","errorCategory":"conceptual_misunderstanding"},{"key":"mountains","text":"Metal and precious stones could only be obtained in the mountains"},{"key":"mining-ban","text":"Its laws forbade mining"}],"answer":"mountains"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-building-material', 'history-early-civilizations/check-plenty-and-scarcity', 'geo-building-material', 'history-early-civilizations/clay-civilization', 'single_choice', 1, 2, '{"key":"geo-building-material","concept":"clay-civilization","difficulty":1,"prompt":"What was the main building material of Mesopotamian architecture?","explanation":"Mesopotamian architecture was almost entirely mud brick, made from the clay that was everywhere.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"mud-brick","text":"Mud brick"},{"key":"cut-stone","text":"Cut stone","errorCategory":"related_concept_confusion"},{"key":"timber","text":"Timber"},{"key":"bronze","text":"Bronze"}],"answer":"mud-brick"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-match-resources', 'history-early-civilizations/check-plenty-and-scarcity', 'geo-match-resources', 'history-early-civilizations/scarce-resources', 'matching', 3, 3, '{"key":"geo-match-resources","concept":"scarce-resources","difficulty":3,"prompt":"Match each material to how southern Mesopotamia obtained or used it.","explanation":"Clay was everywhere; bitumen came from springs at Hīt; metal only from the mountains; date-palm wood served only for rough beams.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"matching","left":[{"key":"clay","text":"Clay"},{"key":"bitumen","text":"Bitumen"},{"key":"metal","text":"Metal"},{"key":"palm-wood","text":"Date-palm wood"}],"right":[{"key":"mountains","text":"Obtainable only from the mountains"},{"key":"beams","text":"Good only for rough beams"},{"key":"everywhere","text":"Plentiful: used for bricks, pottery and tablets"},{"key":"hit","text":"From springs at Hīt on the Euphrates"}],"answer":{"clay":"everywhere","bitumen":"hit","metal":"mountains","palm-wood":"beams"}}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-ur-graves', 'history-early-civilizations/check-plenty-and-scarcity', 'geo-ur-graves', 'history-early-civilizations/long-distance-trade', 'single_choice', 2, 4, '{"key":"geo-ur-graves","concept":"long-distance-trade","difficulty":2,"prompt":"Graves at Ur from the Early Dynastic period contained objects made of which imported materials?","explanation":"The graves at Ur revealed long-distance trade through objects of imported gold, silver, lapis lazuli and carnelian.","errorCategory":"misremembered_fact","citations":[{"source":"met-mesopotamia-8000-2000"}],"kind":"single_choice","options":[{"key":"iron-steel","text":"Iron and steel","errorCategory":"misremembered_fact"},{"key":"gold-lapis","text":"Gold, silver, lapis lazuli and carnelian"},{"key":"jade-porcelain","text":"Jade and porcelain"},{"key":"glass-silk","text":"Glass and silk"}],"answer":"gold-lapis"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-trade-partners', 'history-early-civilizations/check-plenty-and-scarcity', 'geo-trade-partners', 'history-early-civilizations/long-distance-trade', 'single_choice', 1, 5, '{"key":"geo-trade-partners","concept":"long-distance-trade","difficulty":1,"prompt":"According to excavated objects and texts, which regions did Early Dynastic Sumer trade with?","explanation":"Evidence shows trade with the Persian Gulf region, Iran, Afghanistan and the cities of the Indus Valley.","errorCategory":"misremembered_fact","citations":[{"source":"met-mesopotamia-8000-2000"}],"kind":"single_choice","options":[{"key":"china-japan","text":"China and Japan"},{"key":"gulf-iran","text":"The Persian Gulf, Iran, Afghanistan and the Indus Valley"},{"key":"europe","text":"Western Europe"},{"key":"americas","text":"The Americas"}],"answer":"gulf-iran"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/geo-salt-debate', 'history-early-civilizations/check-plenty-and-scarcity', 'geo-salt-debate', 'history-early-civilizations/salinization-debate', 'single_choice', 3, 6, '{"key":"geo-salt-debate","concept":"salinization-debate","difficulty":3,"prompt":"In 1958 Jacobsen and Adams argued that rising salt and silt in the soil contributed to the decline of southern Mesopotamian civilization. How should this idea be treated?","explanation":"It is a scholarly argument, and Powell published a critique of it in 1985. Contested interpretations should be presented as debated.","errorCategory":"misremembered_fact","citations":[{"source":"jacobsen-adams-1958"},{"source":"powell-1985"}],"kind":"single_choice","options":[{"key":"fact","text":"As a proven fact that all historians accept","errorCategory":"conceptual_misunderstanding"},{"key":"debated","text":"As a debated interpretation: other scholars, such as Marvin Powell in 1985, have challenged it"},{"key":"myth","text":"As a myth taken from ancient Mesopotamian stories"},{"key":"unquestioned","text":"As an idea no one has ever questioned","errorCategory":"conceptual_misunderstanding"}],"answer":"debated"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.learning_activities (id, template_id, objective_id, key, kind, title, position, competency_ids, estimated_minutes, sections, introduces_ids, target_stage, question_count) values ('history-early-civilizations/lesson-hills-to-floodplain', 'history-early-civilizations', 'history-early-civilizations/trace-farming', 'lesson-hills-to-floodplain', 'lesson', 'From the hills to the floodplain', 0, array['history-early-civilizations/agriculture']::text[], 6, '[{"heading":"A word about dates","paragraphs":["Dates for this period carry a “c.” (circa, “about”) for a reason. There is no universally accepted chronology for the early Near East, and reign dates in Babylonia are certain only back to 747 BCE. This course uses the dates published by The Metropolitan Museum of Art."],"certainty":"established","citations":[{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"}]},{"heading":"Farming begins in the hills","paragraphs":["Farming seems to have begun in the wetter hill country bordering Mesopotamia, in the 10th millennium BCE. By 8000 BCE farming villages were established in northern Mesopotamia, at the eastern end of the Fertile Crescent.","At Jarmo, about 8000–7000 BCE, archaeologists found the first evidence of domesticated wheat and barley, and of domesticated sheep, goats, pigs and cattle."],"certainty":"consensus","citations":[{"sourceId":"history-early-civilizations/britannica-mesopotamia"},{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"}]},{"heading":"Irrigation opens the south","paragraphs":["Early in the sixth millennium BCE, farming communities that relied on irrigation instead of rain settled ever further south along the Tigris and Euphrates. Irrigation farming on the alluvial plain has gone on for about 7,000 years since."],"certainty":"consensus","citations":[{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"},{"sourceId":"history-early-civilizations/britannica-tigris-euphrates"}]},{"heading":"A surplus to trade","paragraphs":["Irrigated fields, herds, fisheries and date palms produced more grain, wool, fish, dates and reed goods than people needed. That surplus could pay for the wood, stone and metal the south lacked. The date palm was so important it has been called virtually the national tree of Iraq."],"certainty":"established","citations":[{"sourceId":"history-early-civilizations/britannica-mesopotamia"}]}]'::jsonb, array['history-early-civilizations/first-farmers', 'history-early-civilizations/irrigation-moves-south', 'history-early-civilizations/abundant-produce', 'history-early-civilizations/chronology-uncertain']::text[], null, null) on conflict (id) do update set template_id = excluded.template_id, objective_id = excluded.objective_id, key = excluded.key, kind = excluded.kind, title = excluded.title, position = excluded.position, competency_ids = excluded.competency_ids, estimated_minutes = excluded.estimated_minutes, sections = excluded.sections, introduces_ids = excluded.introduces_ids, target_stage = excluded.target_stage, question_count = excluded.question_count;
insert into public.learning_activities (id, template_id, objective_id, key, kind, title, position, competency_ids, estimated_minutes, sections, introduces_ids, target_stage, question_count) values ('history-early-civilizations/check-hills-to-floodplain', 'history-early-civilizations', 'history-early-civilizations/trace-farming', 'check-hills-to-floodplain', 'assessment', 'Check: from the hills to the floodplain', 1, array['history-early-civilizations/agriculture']::text[], null, null, '{}'::text[], 2, 5) on conflict (id) do update set template_id = excluded.template_id, objective_id = excluded.objective_id, key = excluded.key, kind = excluded.kind, title = excluded.title, position = excluded.position, competency_ids = excluded.competency_ids, estimated_minutes = excluded.estimated_minutes, sections = excluded.sections, introduces_ids = excluded.introduces_ids, target_stage = excluded.target_stage, question_count = excluded.question_count;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-where-began', 'history-early-civilizations/check-hills-to-floodplain', 'agri-where-began', 'history-early-civilizations/first-farmers', 'single_choice', 1, 0, '{"key":"agri-where-began","concept":"first-farmers","difficulty":1,"prompt":"Where did farming begin, before it reached the southern floodplain?","explanation":"Farming seems to have begun in the higher-rainfall hill country on Mesopotamia’s borders, long before irrigation opened the south.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"marshes","text":"In the marshes of the far south","errorCategory":"misremembered_fact"},{"key":"hills","text":"In the wetter hilly borders of Mesopotamia"},{"key":"desert","text":"In the Arabian desert"},{"key":"cities","text":"Inside the first cities","errorCategory":"conceptual_misunderstanding"}],"answer":"hills"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-order-events', 'history-early-civilizations/check-hills-to-floodplain', 'agri-order-events', 'history-early-civilizations/irrigation-moves-south', 'ordering', 2, 1, '{"key":"agri-order-events","concept":"irrigation-moves-south","difficulty":2,"prompt":"Put these developments in order, earliest first.","explanation":"Jarmo (c. 8000–7000 BCE), irrigation farmers moving south (early 6th millennium BCE), Ubaid culture (c. 5000–4000 BCE), then Uruk as the largest settlement (by c. 3200 BCE).","errorCategory":"misremembered_fact","citations":[{"source":"met-mesopotamia-8000-2000"},{"source":"met-uruk"}],"kind":"ordering","entries":[{"key":"ubaid","text":"Ubaid culture arises in the south"},{"key":"uruk","text":"Uruk is the largest settlement in southern Mesopotamia"},{"key":"jarmo","text":"First evidence of domesticated grains and animals at Jarmo"},{"key":"south","text":"Irrigation farmers settle further south along the rivers"}],"answer":["jarmo","south","ubaid","uruk"]}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-jarmo-animals', 'history-early-civilizations/check-hills-to-floodplain', 'agri-jarmo-animals', 'history-early-civilizations/first-farmers', 'single_choice', 1, 2, '{"key":"agri-jarmo-animals","concept":"first-farmers","difficulty":1,"prompt":"At Jarmo, the earliest evidence of which domesticated animals has been found?","explanation":"Jarmo (c. 8000–7000 BCE) has the first evidence of domesticated sheep, goats, pigs and cattle, along with wheat and barley.","errorCategory":"misremembered_fact","citations":[{"source":"met-mesopotamia-8000-2000"}],"kind":"single_choice","options":[{"key":"horses","text":"Horses and camels","errorCategory":"misremembered_fact"},{"key":"chickens","text":"Chickens and ducks"},{"key":"sheep-goat","text":"Sheep, goats, pigs and cattle"},{"key":"llamas","text":"Llamas and alpacas"}],"answer":"sheep-goat"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-what-allowed-south', 'history-early-civilizations/check-hills-to-floodplain', 'agri-what-allowed-south', 'history-early-civilizations/irrigation-moves-south', 'single_choice', 2, 3, '{"key":"agri-what-allowed-south","concept":"irrigation-moves-south","difficulty":2,"prompt":"What allowed farmers to settle the dry southern plain in the sixth millennium BCE?","explanation":"The new southern communities relied on irrigation rather than rainfall.","errorCategory":"misremembered_fact","citations":[{"source":"met-mesopotamia-8000-2000"}],"kind":"single_choice","options":[{"key":"more-rain","text":"The climate became much rainier","errorCategory":"conceptual_misunderstanding"},{"key":"irrigation","text":"Irrigation: bringing river water to the fields"},{"key":"terraces","text":"Terraces cut into mountainsides","errorCategory":"incorrect_application"},{"key":"imported-food","text":"Food imported from Egypt"}],"answer":"irrigation"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-surplus', 'history-early-civilizations/check-hills-to-floodplain', 'agri-surplus', 'history-early-civilizations/abundant-produce', 'single_choice', 2, 4, '{"key":"agri-surplus","concept":"abundant-produce","difficulty":2,"prompt":"Which goods could southern Mesopotamia produce in surplus, enough to export?","explanation":"Farm, herd, fishery, date-palm and reed products were plentiful. Timber, stone and metal were what the south lacked.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"grain-dates","text":"Grain, dates, wool, fish and reed products"},{"key":"timber-metal","text":"Timber and metal","errorCategory":"related_concept_confusion"},{"key":"stone-gems","text":"Building stone and gems","errorCategory":"related_concept_confusion"},{"key":"silk","text":"Silk and spices"}],"answer":"grain-dates"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-why-circa', 'history-early-civilizations/check-hills-to-floodplain', 'agri-why-circa', 'history-early-civilizations/chronology-uncertain', 'single_choice', 3, 5, '{"key":"agri-why-circa","concept":"chronology-uncertain","difficulty":3,"prompt":"Why do dates for early Mesopotamia come with “c.” (circa)?","explanation":"Neither documents nor scientific methods fix early events exactly, so dates are approximate and chronologies differ.","errorCategory":"misremembered_fact","citations":[{"source":"met-mesopotamia-8000-2000"}],"kind":"single_choice","options":[{"key":"carbon-exact","text":"Because carbon-14 dating gives exact years, so “c.” is just a habit","errorCategory":"conceptual_misunderstanding"},{"key":"invented","text":"Because the dates are invented for convenience"},{"key":"uncertain","text":"Because events can’t be fixed exactly in time; reign dates in Babylonia are certain only back to 747 BCE"},{"key":"unstudied","text":"Because historians have not studied the period yet"}],"answer":"uncertain"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-palm-wood', 'history-early-civilizations/check-hills-to-floodplain', 'agri-palm-wood', 'history-early-civilizations/abundant-produce', 'single_choice', 3, 6, '{"key":"agri-palm-wood","concept":"abundant-produce","difficulty":3,"prompt":"The date palm was hugely important in Mesopotamia. What was its wood good for?","explanation":"Date-palm wood was suitable only for rough beams, one reason good timber had to be imported.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"fine-work","text":"Fine furniture and shipbuilding","errorCategory":"misremembered_fact"},{"key":"rough-beams","text":"Only rough beams, not finer work"},{"key":"nothing","text":"Nothing: it was never used"},{"key":"smelting","text":"Charcoal for smelting iron"}],"answer":"rough-beams"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.learning_activities (id, template_id, objective_id, key, kind, title, position, competency_ids, estimated_minutes, sections, introduces_ids, target_stage, question_count) values ('history-early-civilizations/lesson-villages-to-cities', 'history-early-civilizations', 'history-early-civilizations/explain-first-cities', 'lesson-villages-to-cities', 'lesson', 'Villages become cities', 0, array['history-early-civilizations/agriculture']::text[], 7, '[{"heading":"The Ubaid culture","paragraphs":["Around 5000–4000 BCE (in the Met’s dates; other scholars start earlier), the Ubaid culture arose in the south, known for painted pottery made on a slow wheel. Its style spread and replaced local pottery across Mesopotamia and beyond.","At Eridu, people built a sequence of ever larger mud-brick temples."],"certainty":"consensus","citations":[{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"}]},{"heading":"Fewer, bigger settlements","paragraphs":["Between about 4000 and 3500 BCE, smaller villages gave way to fewer but larger settlements. From about 3500 to 3000 BCE cities appeared across the region, most of all in the south, centred on great mud-brick temples raised on platforms.","By about 3200 BCE Uruk was the largest settlement in southern Mesopotamia, if not the world: a true city with monumental buildings decorated with mosaics of painted clay cones, new kinds of sculpture, and metal casting."],"certainty":"consensus","citations":[{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"},{"sourceId":"history-early-civilizations/met-uruk"}]},{"heading":"Why writing appeared","paragraphs":["A bigger, more centralised economy needed better records. At Uruk, simple pictographs on clay tablets tracked goods and the rations given to workers. These were the forerunners of cuneiform.","Older clay tokens used for record keeping slowly disappeared. Signs were first drawn into clay and later pressed in with a reed stylus, and cylinder seals largely replaced stamp seals."],"certainty":"consensus","citations":[{"sourceId":"history-early-civilizations/met-uruk"},{"sourceId":"history-early-civilizations/met-mesopotamia-8000-2000"}]}]'::jsonb, array['history-early-civilizations/ubaid-culture', 'history-early-civilizations/uruk-period', 'history-early-civilizations/writing-for-administration']::text[], null, null) on conflict (id) do update set template_id = excluded.template_id, objective_id = excluded.objective_id, key = excluded.key, kind = excluded.kind, title = excluded.title, position = excluded.position, competency_ids = excluded.competency_ids, estimated_minutes = excluded.estimated_minutes, sections = excluded.sections, introduces_ids = excluded.introduces_ids, target_stage = excluded.target_stage, question_count = excluded.question_count;
insert into public.learning_activities (id, template_id, objective_id, key, kind, title, position, competency_ids, estimated_minutes, sections, introduces_ids, target_stage, question_count) values ('history-early-civilizations/check-villages-to-cities', 'history-early-civilizations', 'history-early-civilizations/explain-first-cities', 'check-villages-to-cities', 'assessment', 'Check: villages become cities', 1, array['history-early-civilizations/agriculture']::text[], null, null, '{}'::text[], 3, 5) on conflict (id) do update set template_id = excluded.template_id, objective_id = excluded.objective_id, key = excluded.key, kind = excluded.kind, title = excluded.title, position = excluded.position, competency_ids = excluded.competency_ids, estimated_minutes = excluded.estimated_minutes, sections = excluded.sections, introduces_ids = excluded.introduces_ids, target_stage = excluded.target_stage, question_count = excluded.question_count;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-ubaid-known-for', 'history-early-civilizations/check-villages-to-cities', 'agri-ubaid-known-for', 'history-early-civilizations/ubaid-culture', 'single_choice', 1, 0, '{"key":"agri-ubaid-known-for","concept":"ubaid-culture","difficulty":1,"prompt":"What is the Ubaid culture best known for?","explanation":"Ubaid culture is recognised by its painted pottery made on a slow wheel, which spread widely.","errorCategory":"misremembered_fact","citations":[{"source":"met-mesopotamia-8000-2000"}],"kind":"single_choice","options":[{"key":"laws","text":"The first written law codes","errorCategory":"related_concept_confusion"},{"key":"pottery","text":"Distinctive painted pottery made on a slow wheel"},{"key":"pyramids","text":"Stone pyramids"},{"key":"iron","text":"Iron tools"}],"answer":"pottery"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-eridu', 'history-early-civilizations/check-villages-to-cities', 'agri-eridu', 'history-early-civilizations/ubaid-culture', 'single_choice', 2, 1, '{"key":"agri-eridu","concept":"ubaid-culture","difficulty":2,"prompt":"What was built at Eridu during the Ubaid period?","explanation":"Eridu saw a series of ever larger mud-brick temples. The wall traditionally credited to Gilgamesh surrounded Uruk, much later.","errorCategory":"misremembered_fact","citations":[{"source":"met-mesopotamia-8000-2000"},{"source":"met-uruk"}],"kind":"single_choice","options":[{"key":"temples","text":"A sequence of ever more massive mud-brick temples"},{"key":"stone-palace","text":"A stone palace"},{"key":"gilgamesh-wall","text":"A great city wall credited to Gilgamesh","errorCategory":"related_concept_confusion"},{"key":"harbour","text":"A stone harbour"}],"answer":"temples"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-settlement-change', 'history-early-civilizations/check-villages-to-cities', 'agri-settlement-change', 'history-early-civilizations/uruk-period', 'single_choice', 2, 2, '{"key":"agri-settlement-change","concept":"uruk-period","difficulty":2,"prompt":"Between about 4000 and 3500 BCE, how did settlement in the south change?","explanation":"Smaller Ubaid villages gradually gave way to fewer, larger settlements, and the Uruk culture emerged.","errorCategory":"misremembered_fact","citations":[{"source":"met-mesopotamia-8000-2000"}],"kind":"single_choice","options":[{"key":"nomads","text":"People abandoned settlements and became nomads","errorCategory":"conceptual_misunderstanding"},{"key":"north","text":"Settlements emptied as people moved north"},{"key":"fewer-larger","text":"Smaller villages gave way to fewer but larger settlements"},{"key":"no-change","text":"Nothing changed"}],"answer":"fewer-larger"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-first-records', 'history-early-civilizations/check-villages-to-cities', 'agri-first-records', 'history-early-civilizations/writing-for-administration', 'single_choice', 2, 3, '{"key":"agri-first-records","concept":"writing-for-administration","difficulty":2,"prompt":"What did the earliest pictographs on clay tablets at Uruk record?","explanation":"Writing began as record keeping: pictographs tracked goods and workers’ rations. Stories such as those about Gilgamesh came later.","errorCategory":"misremembered_fact","citations":[{"source":"met-uruk"}],"kind":"single_choice","options":[{"key":"epics","text":"Poems and epics about heroes","errorCategory":"related_concept_confusion"},{"key":"goods-rations","text":"The management of goods and the rations given to workers"},{"key":"laws","text":"Law codes","errorCategory":"related_concept_confusion"},{"key":"prayers","text":"Prayers to the gods"}],"answer":"goods-rations"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-order-records', 'history-early-civilizations/check-villages-to-cities', 'agri-order-records', 'history-early-civilizations/writing-for-administration', 'ordering', 3, 4, '{"key":"agri-order-records","concept":"writing-for-administration","difficulty":3,"prompt":"Put these record-keeping methods in the order they developed, earliest first.","explanation":"Clay tokens gradually disappeared as cuneiform developed; signs were first incised and later impressed with a reed stylus.","errorCategory":"misremembered_fact","citations":[{"source":"met-mesopotamia-8000-2000"}],"kind":"ordering","entries":[{"key":"impressed","text":"Signs pressed into clay with a reed stylus"},{"key":"tokens","text":"Variously shaped clay tokens"},{"key":"incised","text":"Signs drawn (incised) into clay tablets"}],"answer":["tokens","incised","impressed"]}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-true-city', 'history-early-civilizations/check-villages-to-cities', 'agri-true-city', 'history-early-civilizations/uruk-period', 'single_choice', 3, 5, '{"key":"agri-true-city","concept":"uruk-period","difficulty":3,"prompt":"Around 3200 BCE Uruk was the largest settlement in southern Mesopotamia, if not the world. Which description fits the evidence?","explanation":"Uruk had monumental decorated mud-brick buildings, new sculpture and metalwork, and written records. The first empire came later, under Sargon of Akkad.","errorCategory":"misremembered_fact","citations":[{"source":"met-uruk"},{"source":"met-mesopotamia-8000-2000"}],"kind":"single_choice","options":[{"key":"million","text":"A city of over a million people","errorCategory":"misremembered_fact"},{"key":"empire","text":"The capital of the first empire","errorCategory":"related_concept_confusion"},{"key":"monumental","text":"A city of monumental mud-brick buildings, new art and record keeping"},{"key":"stone","text":"A city built entirely of cut stone"}],"answer":"monumental"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/agri-seals', 'history-early-civilizations/check-villages-to-cities', 'agri-seals', 'history-early-civilizations/uruk-period', 'single_choice', 1, 6, '{"key":"agri-seals","concept":"uruk-period","difficulty":1,"prompt":"During the Uruk period, stamp seals were largely replaced by what?","explanation":"Cylinder seals largely replaced stamp seals and allowed a wider range of designs.","errorCategory":"misremembered_fact","citations":[{"source":"met-mesopotamia-8000-2000"}],"kind":"single_choice","options":[{"key":"coins","text":"Coins","errorCategory":"misremembered_fact"},{"key":"cylinder","text":"Cylinder seals"},{"key":"ink","text":"Signatures in ink"},{"key":"wax","text":"Wax seals"}],"answer":"cylinder"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.learning_activities (id, template_id, objective_id, key, kind, title, position, competency_ids, estimated_minutes, sections, introduces_ids, target_stage, question_count) values ('history-early-civilizations/check-floodplain-challenge', 'history-early-civilizations', 'history-early-civilizations/connect-land-and-cities', 'check-floodplain-challenge', 'assessment', 'Check: the challenge of the floodplain', 0, array['history-early-civilizations/geography', 'history-early-civilizations/agriculture']::text[], null, null, '{}'::text[], 4, 5) on conflict (id) do update set template_id = excluded.template_id, objective_id = excluded.objective_id, key = excluded.key, kind = excluded.kind, title = excluded.title, position = excluded.position, competency_ids = excluded.competency_ids, estimated_minutes = excluded.estimated_minutes, sections = excluded.sections, introduces_ids = excluded.introduces_ids, target_stage = excluded.target_stage, question_count = excluded.question_count;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/review-temple-plan', 'history-early-civilizations/check-floodplain-challenge', 'review-temple-plan', 'history-early-civilizations/clay-civilization', 'single_choice', 2, 0, '{"key":"review-temple-plan","concept":"clay-civilization","difficulty":2,"prompt":"A city in the far south plans a new temple. Which plan best fits the resources available locally?","explanation":"Clay was everywhere and stone and good timber were scarce, so southern builders used mud brick and imported what they lacked.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"stone","text":"Cut stone from nearby quarries","errorCategory":"incorrect_application"},{"key":"mud-brick","text":"Mud brick from local clay, with any fine timber or stone brought in by trade"},{"key":"hardwood","text":"Local hardwood beams throughout","errorCategory":"incorrect_application"},{"key":"iron","text":"Iron girders"}],"answer":"mud-brick"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/review-land-of-plenty', 'history-early-civilizations/check-floodplain-challenge', 'review-land-of-plenty', 'history-early-civilizations/low-rainfall', 'single_choice', 3, 1, '{"key":"review-land-of-plenty","concept":"low-rainfall","difficulty":3,"prompt":"Why could irrigation turn the dry south into a land of plenty?","explanation":"Water was the missing ingredient. The soil was very fertile, and with irrigation and drainage it could feed a large population.","errorCategory":"misremembered_fact","citations":[{"source":"britannica-mesopotamia"}],"kind":"single_choice","options":[{"key":"fertile","text":"The soil is extremely fertile: with water and drainage it produces in abundance"},{"key":"more-rain","text":"Irrigation increased the rainfall","errorCategory":"conceptual_misunderstanding"},{"key":"no-drainage","text":"Irrigation removed any need for drainage","errorCategory":"incorrect_application"},{"key":"ores","text":"Canals carried metal ores to the fields"}],"answer":"fertile"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/review-cause-effect', 'history-early-civilizations/check-floodplain-challenge', 'review-cause-effect', 'history-early-civilizations/irrigation-moves-south', 'matching', 3, 2, '{"key":"review-cause-effect","concept":"irrigation-moves-south","difficulty":3,"prompt":"Match each condition in southern Mesopotamia to a response or result.","explanation":"Little rain led to irrigation canals; missing metal and stone led to trade; slow rivers deposit silt, raising their beds so they overflow.","errorCategory":"incorrect_application","citations":[{"source":"britannica-mesopotamia"}],"kind":"matching","left":[{"key":"little-rain","text":"Very little rain"},{"key":"no-metal","text":"No local metal or stone"},{"key":"slow-rivers","text":"Slow, silt-laden rivers"}],"right":[{"key":"raised-beds","text":"Raised riverbeds and overflowing banks"},{"key":"canals","text":"Canals bringing river water to fields"},{"key":"trade","text":"Trade with distant regions"}],"answer":{"little-rain":"canals","no-metal":"trade","slow-rivers":"raised-beds"}}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/review-rations-writing', 'history-early-civilizations/check-floodplain-challenge', 'review-rations-writing', 'history-early-civilizations/writing-for-administration', 'single_choice', 2, 3, '{"key":"review-rations-writing","concept":"writing-for-administration","difficulty":2,"prompt":"Growing cities had to track goods and the rations handed out to workers. Which development does the evidence connect to this need?","explanation":"The earliest pictographs at Uruk recorded goods and workers’ rations: writing grew out of administration.","errorCategory":"misremembered_fact","citations":[{"source":"met-uruk"}],"kind":"single_choice","options":[{"key":"coins","text":"The invention of coins","errorCategory":"misremembered_fact"},{"key":"writing","text":"Early writing on clay tablets"},{"key":"ziggurats","text":"Ziggurats","errorCategory":"related_concept_confusion"},{"key":"empire","text":"The first empire"}],"answer":"writing"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/review-salt-claim', 'history-early-civilizations/check-floodplain-challenge', 'review-salt-claim', 'history-early-civilizations/salinization-debate', 'single_choice', 3, 4, '{"key":"review-salt-claim","concept":"salinization-debate","difficulty":3,"prompt":"A student writes: “Salt in the soil destroyed Sumer.” What is the best correction?","explanation":"Jacobsen and Adams argued for a contributing role; Powell challenged the theory. A careful historian presents it as debated, not as a simple fact.","errorCategory":"misremembered_fact","citations":[{"source":"jacobsen-adams-1958"},{"source":"powell-1985"}],"kind":"single_choice","options":[{"key":"correct","text":"It is correct as written","errorCategory":"conceptual_misunderstanding"},{"key":"debated","text":"Some historians argued salt and silt contributed to decline, but the idea is debated"},{"key":"no-effect","text":"Salt has no effect on farming at all","errorCategory":"incorrect_application"},{"key":"floods","text":"Sumer was destroyed by a single great flood instead"}],"answer":"debated"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
insert into public.assessment_items (id, activity_id, key, concept_id, kind, difficulty, position, definition) values ('history-early-civilizations/review-dates-differ', 'history-early-civilizations/check-floodplain-challenge', 'review-dates-differ', 'history-early-civilizations/chronology-uncertain', 'single_choice', 2, 5, '{"key":"review-dates-differ","concept":"chronology-uncertain","difficulty":2,"prompt":"Two books give different dates for the Ubaid period. What is the most likely reason?","explanation":"No universally accepted chronology exists for the early Near East, so reasonable scholars give different dates.","errorCategory":"misremembered_fact","citations":[{"source":"met-mesopotamia-8000-2000"}],"kind":"single_choice","options":[{"key":"one-wrong","text":"One of the books must simply be wrong","errorCategory":"conceptual_misunderstanding"},{"key":"uncertain","text":"Early dates are uncertain, and scholars use different evidence and chronologies"},{"key":"twice","text":"The Ubaid period happened twice"},{"key":"change","text":"Historians change all dates every year"}],"answer":"uncertain"}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, key = excluded.key, concept_id = excluded.concept_id, kind = excluded.kind, difficulty = excluded.difficulty, position = excluded.position, definition = excluded.definition;
